from itertools import permutations

def solve_puzzle():
    people = ['Logan', 'Reese', 'Riley', 'Taylor']
    colors = ['blue', 'green', 'orange', 'white']
    pets = ['bird', 'cat', 'dog', 'rabbit']
    drinks = ['cocoa', 'coffee', 'tea', 'water']

    # Try all combinations
    for person_perm in permutations(people):
        for color_perm in permutations(colors):
            for pet_perm in permutations(pets):
                for drink_perm in permutations(drinks):
                    # Create the assignment for each house
                    houses = [(person_perm[i], color_perm[i], pet_perm[i], drink_perm[i]) 
                              for i in range(4)]

                    if is_valid(houses):
                        # Found the solution
                        for person, color, pet, drink in houses:
                            if color == 'green':
                                return person

    return None

def is_valid(houses):
    # Create helper mapping: person -> house index (0-3)
    person_to_house = {person: i for i, (person, _, _, _) in enumerate(houses)}

    # Helper functions
    def adjacent(h1, h2):
        return abs(h1 - h2) == 1

    def immediately_left(h1, h2):
        return h2 - h1 == 1

    # Clue 1: Cocoa drinker immediately left of Reese
    reese_house = person_to_house['Reese']
    for i, (_, _, _, drink) in enumerate(houses):
        if drink == 'cocoa':
            if not immediately_left(i, reese_house):
                return False

    # Clue 2: Blue house person drinks cocoa
    for _, color, _, drink in houses:
        if (color == 'blue') != (drink == 'cocoa'):
            return False

    # Clue 3: Bird owner adjacent to Taylor
    taylor_house = person_to_house['Taylor']
    for i, (_, _, pet, _) in enumerate(houses):
        if pet == 'bird' and not adjacent(i, taylor_house):
            return False

    # Clue 4: Cat owner is Riley
    riley_house = person_to_house['Riley']
    if houses[riley_house][2] != 'cat':
        return False

    # Clue 5: Logan is bird owner
    logan_house = person_to_house['Logan']
    if houses[logan_house][2] != 'bird':
        return False

    # Clue 6: Green house person owns dog
    for _, color, pet, _ in houses:
        if (color == 'green') != (pet == 'dog'):
            return False

    # Clue 7: Blue house person owns cat
    for _, color, pet, _ in houses:
        if (color == 'blue') != (pet == 'cat'):
            return False

    # Clue 8: Orange house adjacent to Reese
    for i, (_, color, _, _) in enumerate(houses):
        if color == 'orange' and not adjacent(i, reese_house):
            return False

    # Clue 9: Coffee drinker is Logan
    if houses[logan_house][3] != 'coffee':
        return False

    # Clue 10: Rabbit owner doesn't drink water
    for _, _, pet, drink in houses:
        if pet == 'rabbit' and drink == 'water':
            return False

    # Clue 11: Taylor adjacent to dog owner
    for i, (_, _, pet, _) in enumerate(houses):
        if pet == 'dog' and not adjacent(taylor_house, i):
            return False

    return True

answer = solve_puzzle()
print(f"ANSWER: {answer}")
